//! hub-core's pydantic-compatible validation against pydantic 2.13.5 itself (golden/models.json, generated by
//! backend/parity/gen/gen_models_golden.py). Content models are checked here; API body models in agent-hub's tests.

use hub_core::models::by_name;
use hub_core::pyd;
use hub_core::value::PyValue;
use serde_json::Value;

#[test]
fn content_models_match_pydantic() -> Result<(), Box<dyn std::error::Error>> {
    let golden: Vec<Value> = serde_json::from_str(include_str!("golden/models.json"))?;
    let mut checked = 0;
    let mut failures = Vec::new();
    for case in &golden {
        let name = case["model"].as_str().unwrap_or_default();
        let Some(model) = by_name(name) else { continue };
        // YAML-text inputs carry what JSON cannot (non-str keys); they are loaded like content frontmatter
        let input = match case["yaml"].as_str() {
            Some(text) => hub_core::yaml::load(text, hub_core::yaml::Loader::Safe)?,
            None => PyValue::from_json(&case["input"]),
        };
        let got = pyd::validate(model, &input);
        checked += 1;
        match (case["ok"].as_bool(), got) {
            (Some(true), Ok(v)) => {
                if pyd::dump_json(model, &v, false) != case["dump"] {
                    failures.push(format!(
                        "{name} {}: dump {}",
                        case.get("input").unwrap_or(&case["yaml"]),
                        pyd::dump_json(model, &v, false)
                    ));
                }
                if pyd::dump_json(model, &v, true) != case["dump_exclude_none"] {
                    failures.push(format!(
                        "{name} {}: dump(exclude_none) {}",
                        case.get("input").unwrap_or(&case["yaml"]),
                        pyd::dump_json(model, &v, true)
                    ));
                }
            }
            (Some(false), Err(e)) => {
                if e.errors_json(&[]) != case["errors"] {
                    failures.push(format!(
                        "{name} {}: errors {}",
                        case.get("input").unwrap_or(&case["yaml"]),
                        e.errors_json(&[])
                    ));
                }
                if e.to_string() != case["str"].as_str().unwrap_or_default() {
                    failures.push(format!(
                        "{name} {}: str\n{e}\n--- want\n{}",
                        case.get("input").unwrap_or(&case["yaml"]),
                        case["str"].as_str().unwrap_or_default()
                    ));
                }
            }
            (want, got) => failures.push(format!(
                "{name} {}: want ok={want:?}, got {:?}",
                case.get("input").unwrap_or(&case["yaml"]),
                got.map(|_| ())
            )),
        }
    }
    assert!(checked > 30, "only {checked} content cases");
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
    Ok(())
}
